1	import { flexRender, type Table as TanstackTable } from "@tanstack/react-table";
2	import {
3		Pagination,
4		PaginationContent,
5		PaginationFirstButton,
6		PaginationItem,
7		PaginationLastButton,
8		PaginationNextButton,
9		PaginationPreviousButton,
10	} from "@/components/ui/pagination";
11	import {
12		Select,
13		SelectContent,
14		SelectItem,
15		SelectTrigger,
16		SelectValue,
17	} from "@/components/ui/select";
18	import {
19		Table,
20		TableBody,
21		TableCell,
22		TableHead,
23		TableHeader,
24		TableRow,
25	} from "@/components/ui/table";
26	import { cn } from "@/utils";
27	
28	const shouldIgnoreRowClick = (target: EventTarget | null) =>
29		target instanceof Element &&
30		target.closest(
31			'a, button, input, select, textarea, [role="button"], [role="checkbox"], [role="menuitem"], [role="switch"], [data-row-click-ignore="true"]',
32		);
33	
34	export function DataTable<TData>({
35		table,
36		onPrefetchPage,
37		onRowClick,
38	}: {
39		table: TanstackTable<TData>;
40		onPrefetchPage?: (page: number) => void;
41		onRowClick?: (row: TData) => void;
42	}) {
43		return (
44			<div className="flex flex-col gap-4">
45				<div className="rounded-md border overflow-x-auto">
46					<Table>
47						<TableHeader>
48							{table.getHeaderGroups().map((headerGroup) => (
49								<TableRow key={headerGroup.id}>
50									{headerGroup.headers.map((header) => (
51										<TableHead
52											key={header.id}
53											style={{
54												...(header.column.columnDef.maxSize && {
55													maxWidth: `${header.column.columnDef.maxSize}px`,
56												}),
57												...(header.column.columnDef.size && {
58													width: `${header.column.columnDef.size}px`,
59												}),
60											}}
61										>
62											{header.isPlaceholder
63												? null
64												: flexRender(
65														header.column.columnDef.header,
66														header.getContext(),
67													)}
68										</TableHead>
69									))}
70								</TableRow>
71							))}
72						</TableHeader>
73						<TableBody>
74							{table.getRowModel().rows?.length ? (
75								table.getRowModel().rows.map((row) => (
76									<TableRow
77										key={row.id}
78										data-state={row.getIsSelected() && "selected"}
79										className={
80											onRowClick ? "cursor-pointer hover:bg-muted" : undefined
81										}
82										onClick={
83											onRowClick
84												? (event) => {
85														if (shouldIgnoreRowClick(event.target)) return;
86														onRowClick(row.original);
87													}
88												: undefined
89										}
90									>
91										{row.getVisibleCells().map((cell) => (
92											<TableCell
93												key={cell.id}
94												style={{
95													...(cell.column.columnDef.maxSize && {
96														maxWidth: `${cell.column.columnDef.maxSize}px`,
97													}),
98													...(cell.column.columnDef.size && {
99														width: `${cell.column.columnDef.size}px`,
100													}),
101												}}
102											>
103												{flexRender(
104													cell.column.columnDef.cell,
105													cell.getContext(),
106												)}
107											</TableCell>
108										))}
109									</TableRow>
110								))
111							) : (
112								<TableRow>
113									<TableCell
114										colSpan={table.getAllColumns().length}
115										className="h-24 text-center"
116									>
117										No results.
118									</TableCell>
119								</TableRow>
120							)}
121						</TableBody>
122					</Table>
123				</div>
124				<div className="flex flex-row justify-between items-center">
125					<DataTablePageSize table={table} />
126					<DataTablePagination table={table} onPrefetchPage={onPrefetchPage} />
127				</div>
128			</div>
129		);
130	}
131	
132	interface DataTablePageSizeProps<TData> {
133		table: TanstackTable<TData>;
134	}
135	
136	function DataTablePageSize<TData>({ table }: DataTablePageSizeProps<TData>) {
137		return (
138			<div className="flex flex-row items-center gap-2 text-xs text-muted-foreground">
139				<span className="whitespace-nowrap">Items per page</span>
140				<Select
141					value={table.getState().pagination.pageSize.toString()}
142					onValueChange={(value) => {
143						table.setPageSize(Number(value));
144					}}
145				>
146					<SelectTrigger aria-label="Items per page">
147						<SelectValue placeholder="Theme" />
148					</SelectTrigger>
149					<SelectContent>
150						<SelectItem value="5">5</SelectItem>
151						<SelectItem value="10">10</SelectItem>
152						<SelectItem value="25">25</SelectItem>
153						<SelectItem value="50">50</SelectItem>
154					</SelectContent>
155				</Select>
156			</div>
157		);
158	}
159	
160	interface DataTablePaginationProps<TData> {
161		table: TanstackTable<TData>;
162		className?: string;
163		onPrefetchPage?: (page: number) => void;
164	}
165	
166	export function DataTablePagination<TData>({
167		table,
168		className,
169		onPrefetchPage,
170	}: DataTablePaginationProps<TData>) {
171		const totalPages = table.getPageCount();
172		const currentPage = Math.min(
173			Math.ceil(table.getState().pagination.pageIndex + 1),
174			totalPages,
175		);
176	
177		const handlePrefetchFirstPage = () => {
178			if (currentPage > 1) onPrefetchPage?.(1);
179		};
180		const handlePrefetchPreviousPage = () => {
181			if (currentPage > 1) onPrefetchPage?.(currentPage - 1);
182		};
183		const handlePrefetchNextPage = () => {
184			if (currentPage < totalPages) onPrefetchPage?.(currentPage + 1);
185		};
186		const handlePrefetchLastPage = () => {
187			if (currentPage < totalPages) onPrefetchPage?.(totalPages);
188		};
189	
190		return (
191			<Pagination className={cn("justify-end", className)}>
192				<PaginationContent>
193					<PaginationItem>
194						<PaginationFirstButton
195							onClick={() => table.firstPage()}
196							onMouseEnter={handlePrefetchFirstPage}
197							disabled={!table.getCanPreviousPage()}
198						/>
199						<PaginationPreviousButton
200							onClick={() => table.previousPage()}
201							onMouseEnter={handlePrefetchPreviousPage}
202							disabled={!table.getCanPreviousPage()}
203						/>
204					</PaginationItem>
205					<PaginationItem className="text-sm">
206						Page {currentPage.toLocaleString()} of {totalPages.toLocaleString()}
207					</PaginationItem>
208					<PaginationItem>
209						<PaginationNextButton
210							onClick={() => table.nextPage()}
211							onMouseEnter={handlePrefetchNextPage}
212							disabled={!table.getCanNextPage()}
213						/>
214					</PaginationItem>
215					<PaginationItem>
216						<PaginationLastButton
217							onClick={() => table.lastPage()}
218							onMouseEnter={handlePrefetchLastPage}
219							disabled={!table.getCanNextPage()}
220						/>
221					</PaginationItem>
222				</PaginationContent>
223			</Pagination>
224		);
225	}
