1	import {
2		createColumnHelper,
3		getCoreRowModel,
4		useReactTable,
5	} from "@tanstack/react-table";
6	import { render, screen } from "@testing-library/react";
7	import userEvent from "@testing-library/user-event";
8	import { describe, expect, it, vi } from "vitest";
9	import { DataTable } from "./data-table";
10	
11	type TestData = { id: string; name: string };
12	
13	const columnHelper = createColumnHelper<TestData>();
14	const columns = [
15		columnHelper.accessor("name", {
16			header: "Name",
17			cell: (info) => (
18				<>
19					<span>{info.getValue()}</span>
20					<button type="button">Row action {info.row.original.id}</button>
21				</>
22			),
23		}),
24	];
25	
26	const TestTable = ({
27		data,
28		onRowClick,
29	}: {
30		data: TestData[];
31		onRowClick?: (row: TestData) => void;
32	}) => {
33		const table = useReactTable({
34			data,
35			columns,
36			getCoreRowModel: getCoreRowModel(),
37		});
38		return <DataTable table={table} onRowClick={onRowClick} />;
39	};
40	
41	describe("DataTable", () => {
42		const testData: TestData[] = [
43			{ id: "1", name: "Row 1" },
44			{ id: "2", name: "Row 2" },
45		];
46	
47		it("renders rows without cursor-pointer class when onRowClick is not provided", () => {
48			render(<TestTable data={testData} />);
49	
50			const rows = screen.getAllByRole("row");
51			// First row is the header, data rows start at index 1
52			const dataRow = rows[1];
53			expect(dataRow).not.toHaveClass("cursor-pointer");
54		});
55	
56		it("renders rows with cursor-pointer and hover:bg-muted class when onRowClick is provided", () => {
57			render(<TestTable data={testData} onRowClick={vi.fn()} />);
58	
59			const rows = screen.getAllByRole("row");
60			const dataRow = rows[1];
61			expect(dataRow).toHaveClass("cursor-pointer");
62			expect(dataRow).toHaveClass("hover:bg-muted");
63		});
64	
65		it("calls onRowClick with row data when a row is clicked", async () => {
66			const onRowClick = vi.fn();
67			render(<TestTable data={testData} onRowClick={onRowClick} />);
68	
69			await userEvent.click(screen.getByText("Row 1"));
70	
71			expect(onRowClick).toHaveBeenCalledOnce();
72			expect(onRowClick).toHaveBeenCalledWith({ id: "1", name: "Row 1" });
73		});
74	
75		it("does not call onRowClick when a row action is clicked", async () => {
76			const onRowClick = vi.fn();
77			render(<TestTable data={testData} onRowClick={onRowClick} />);
78	
79			await userEvent.click(screen.getByRole("button", { name: "Row action 1" }));
80	
81			expect(onRowClick).not.toHaveBeenCalled();
82		});
83	
84		it("does not call onRowClick when onRowClick is not provided and row is clicked", async () => {
85			render(<TestTable data={testData} />);
86	
87			await userEvent.click(screen.getByText("Row 1"));
88			// No error thrown, row is simply not clickable
89			expect(screen.getByText("Row 1")).toBeInTheDocument();
90		});
91	});
