import {
	Pagination,
	PaginationContent,
	PaginationFirstButton,
	PaginationItem,
	PaginationLastButton,
	PaginationNextButton,
	PaginationPreviousButton,
} from "@/components/ui/pagination";
import {
	Select,
	SelectContent,
	SelectItem,
	SelectTrigger,
	SelectValue,
} from "@/components/ui/select";
import {
	Table,
	TableBody,
	TableCell,
	TableHead,
	TableHeader,
	TableRow,
} from "@/components/ui/table";
import { cn } from "@/utils";

const shouldIgnoreRowClick = (target: EventTarget | null) =>
	target instanceof Element &&
	target.closest(
		'a, button, input, select, textarea, [role="button"], [role="checkbox"], [role="menuitem"], [role="switch"], [data-row-click-ignore="true"]',
	);

export function DataTable<TData>({
	table,
	onPrefetchPage,
	onRowClick,
}: {
	table: TanstackTable<TData>;
	onPrefetchPage?: (page: number) => void;
	onRowClick?: (row: TData) => void;
}) {
	return (
		<div className="flex flex-col gap-4">
			<div className="rounded-md border overflow-x-auto">
				<Table>
					<TableHeader>
						{table.getHeaderGroups().map((headerGroup) => (
							<TableRow key={headerGroup.id}>
								{headerGroup.headers.map((header) => {
									const canResize =
										table.options.enableColumnResizing === true &&
										header.column.getCanResize();
									return (
										<TableHead
											key={header.id}
											className={cn(canResize && "relative")}
											style={{
												...(header.column.columnDef.maxSize && {
													maxWidth: `${header.column.columnDef.maxSize}px`,
												}),
												...(canResize
													? { width: `${header.getSize()}px` }
													: header.column.columnDef.size
														? { width: `${header.column.columnDef.size}px` }
														: {}),
											}}
										>
											{header.isPlaceholder
												? null
												: flexRender(
														header.column.columnDef.header,
														header.getContext(),
													)}
											{canResize && (
												// biome-ignore lint/a11y/useKeyWithMouseEvents: resize handle is a supplementary pointer affordance
												<div
													data-testid={`column-resize-handle-${header.column.id}`}
													role="separator"
													aria-orientation="vertical"
													onMouseDown={header.getResizeHandler()}
													onTouchStart={header.getResizeHandler()}
													onDoubleClick={() => header.column.resetSize()}
													className={cn(
														"absolute right-0 top-0 h-full w-1 cursor-col-resize touch-none select-none bg-border opacity-0 hover:opacity-100",
														header.column.getIsResizing() &&
															"bg-primary opacity-100",
													)}
												/>
											)}
										</TableHead>
									);
								})}
							</TableRow>
						))}
					</TableHeader>
					<TableBody>
						{table.getRowModel().rows?.length ? (
							table.getRowModel().rows.map((row) => (
								<TableRow
									key={row.id}
									data-state={row.getIsSelected() && "selected"}
									className={
										onRowClick ? "cursor-pointer hover:bg-muted" : undefined
									}
									onClick={
										onRowClick
											? (event) => {
													if (shouldIgnoreRowClick(event.target)) return;
													onRowClick(row.original);
												}
											: undefined
									}
								>
									{row.getVisibleCells().map((cell) => {
										const canResize =
											table.options.enableColumnResizing === true &&
											cell.column.getCanResize();
										return (
											<TableCell
												key={cell.id}
												style={{
													...(cell.column.columnDef.maxSize && {
														maxWidth: `${cell.column.columnDef.maxSize}px`,
													}),
													...(canResize
														? { width: `${cell.column.getSize()}px` }
														: cell.column.columnDef.size
															? { width: `${cell.column.columnDef.size}px` }
															: {}),
												}}
											>
												{flexRender(
													cell.column.columnDef.cell,
													cell.getContext(),
												)}
											</TableCell>
										);
									})}
								</TableRow>
							))
						) : (
							<TableRow>
								<TableCell
									colSpan={table.getAllColumns().length}
									className="h-24 text-center"
								>
									No results.
								</TableCell>
							</TableRow>
						)}
					</TableBody>
				</Table>
			</div>
			<div className="flex flex-row justify-between items-center">
				<DataTablePageSize table={table} />
				<DataTablePagination table={table} onPrefetchPage={onPrefetchPage} />
			</div>
		</div>
	);
}

interface DataTablePageSizeProps<TData> {
	table: TanstackTable<TData>;
}

function DataTablePageSize<TData>({ table }: DataTablePageSizeProps<TData>) {
	return (
		<div className="flex flex-row items-center gap-2 text-xs text-muted-foreground">
			<span className="whitespace-nowrap">Items per page</span>
			<Select
				value={table.getState().pagination.pageSize.toString()}
				onValueChange={(value) => {
					table.setPageSize(Number(value));
				}}
			>
				<SelectTrigger aria-label="Items per page">
					<SelectValue placeholder="Theme" />
				</SelectTrigger>
				<SelectContent>
					<SelectItem value="5">5</SelectItem>
					<SelectItem value="10">10</SelectItem>
					<SelectItem value="25">25</SelectItem>
					<SelectItem value="50">50</SelectItem>
				</SelectContent>
			</Select>
		</div>
	);
}

interface DataTablePaginationProps<TData> {
	table: TanstackTable<TData>;
	className?: string;
	onPrefetchPage?: (page: number) => void;
}

export function DataTablePagination<TData>({
	table,
	className,
	onPrefetchPage,
}: DataTablePaginationProps<TData>) {
